function Instagram({size = 20, style}: LogoProps) {
  const gid = 'ig' + useId().replace(/[^a-zA-Z0-9]/g, '')
  return (
    <svg width={size} height={size} viewBox="0 0 20 20" style={style} aria-hidden="true">
      <defs>
        <radialGradient id={gid} cx="0.3" cy="1.1" r="1.4">
          <stop offset="0" stopColor="#FEDA75"/>
          <stop offset="0.28" stopColor="#F58529"/>
          <stop offset="0.55" stopColor="#DD2A7B"/>
          <stop offset="0.82" stopColor="#8134AF"/>
          <stop offset="1" stopColor="#515BD4"/>
        </radialGradient>
      </defs>
      {/* 兜底层：任何情况下至少有官方主色可辨 */}
      <rect {...ROUNDED} fill="#DD2A7B"/>
      <rect {...ROUNDED} fill={'url(#' + gid + ')'}/>
      <path d={INSTAGRAM_GLYPH} fill="#FFFFFF" transform={FIT}/>
    </svg>
  )
}

