const LOGOS: Record<string, (p: LogoProps) => React.JSX.Element> = {
  douyin: Douyin, tiktok: Tiktok, channels: Channels, xhs: Xhs, kuaishou: Kuaishou,
  bilibili: Bilibili, baijiahao: Baijiahao, toutiao: Toutiao, fanqie: Fanqie,
  youtube: Youtube, instagram: Instagram, x: X,
}

export function PlatformLogo({platform, size = 20, style}: {platform: string; size?: number; style?: React.CSSProperties}) {
  const C = LOGOS[platform]
  if (C) return <C size={size} style={style}/>
  return (
    <svg width={size} height={size} viewBox="0 0 20 20" style={style} aria-hidden="true">
      <rect x="1" y="1" width="18" height="18" rx="4.6" fill="#31424A"/>
    </svg>
  )
}
